mapper.select:
SELECT fm.id, fm.code as code, fm.sku_id as skuId, fm.sku_no as skuNo, fm.file_type as fileType, fm.first_category_id as firstCategoryId, fm.first_category_name as firstCategoryName, fm.product_name as productName, a.attach_name as attachName, a.attach_version as attachVersion, a.attach_url as attachUrl, fm.remark as remark, fm.create_user_name as createUserName, fm.update_user_name as updateUserName, fm.create_time as createTime, fm.update_time as updateTime FROM file_management fm LEFT JOIN attachment a on fm.file_id = a.business_id and a.is_deleted=false where ${params.sqlMap.default} AND fm.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
fm.create_time desc
